inline void need(bool v,const char*s){if(!v)throw std::domain_error(s);}
inline constexpr unsigned char surface_table[]{0xd0u,0x13u,0x41u,0x0u,0xa0u,0x7u,0x76u,0x0u,0x40u,0x8u,0x76u,0x0u,0xa0u,0x9u,0x76u,0x0u,0x0u,0xfdu,0x75u,0x0u,0xd0u,0xfcu,0x75u,0x0u,0x60u,0x7u,0x76u,0x0u,0xf0u,0xffu,0x75u,0x0u,0x0u,0x0u,0x76u,0x0u,0x60u,0xfbu,0x75u,0x0u,0x10u,0xfbu,0x75u,0x0u,0xc0u,0xf2u,0x75u,0x0u,0x90u,0xf2u,0x75u,0x0u,0x0u,0xf8u,0x75u,0x0u,0x10u,0xf8u,0x75u,0x0u,0x20u,0xf8u,0x75u,0x0u,0x30u,0xf8u,0x75u,0x0u,0x40u,0xf8u,0x75u,0x0u,0x70u,0xf5u,0x75u,0x0u,0xe0u,0xf7u,0x75u,0x0u,0xf0u,0xf7u,0x75u,0x0u,0x70u,0xfau,0x75u,0x0u,0x40u,0xfau,0x75u,0x0u,0x70u,0x13u,0x41u,0x0u,0xf0u,0x12u,0x41u,0x0u,0x70u,0x12u,0x41u,0x0u,0x80u,0x12u,0x41u,0x0u,0x0u,0x13u,0x41u,0x0u,0xb0u,0x13u,0x41u,0x0u,0xc0u,0x13u,0x41u,0x0u,0x90u,0x12u,0x41u,0x0u,0xc0u,0x12u,0x41u,0x0u};
inline void check_literals(const b::Memory&m){for(unsigned k=0;k<128u;++k)need(m.r8(0x785ef8u+k)==surface_table[k],"1084 complete authentic surface vtable");}
inline std::vector<unsigned char>encode(const std::vector<unsigned char>&row){std::vector<unsigned char>v(2u,0u);for(unsigned k=0;k<row.size();){if(row[k]){v.push_back(row[k]);++k;}else{unsigned stop=k;while(stop<row.size()&&row[stop]==0u&&stop-k<255u)++stop;need(stop>k,"1084 positivezero run");v.push_back(0u);v.push_back(static_cast<unsigned char>(stop-k));k=stop;}}v[0]=static_cast<unsigned char>(v.size());v[1]=static_cast<unsigned char>(v.size()>>8u);return v;}
struct Proof{unsigned address{},size{};unsigned token(unsigned raw,unsigned offset=0u)const{need(offset<size&&raw==address+offset,"1084 exact wholeLIVEfixture allocation+offset relation");return 0xd0840000u+offset;}};
struct World{unsigned root,base;b::Case c;static constexpr unsigned arena_size=1048576u;World(unsigned r,unsigned a,b::Case v):root(r),base(a),c(v){}unsigned receiver()const{return base+0x400u;}unsigned surface()const{return base+0x800u;}unsigned input_record()const{return base+0x1000u;}unsigned pixels()const{return base+0x10000u;}unsigned x()const{return 124u-(c.width-8u)/2u;}unsigned y()const{return 124u-(c.height-8u)/2u;}unsigned pixel_end()const{return pixels()+(y()+c.height)*256u+x();}std::vector<unsigned>allocation_sizes()const{return{c.capacity};}unsigned fixture_count()const{return 1u;}std::vector<unsigned>free_order()const{return{};}
 unsigned pixel(unsigned row,unsigned col)const{if(col+1u<c.width&&(col+c.seed+row)%7u<3u)return 0u;return 1u+b::mix(c.seed+17u*row+31u*col)%255u;}
 std::vector<unsigned char>row(unsigned j)const{std::vector<unsigned char>v;for(unsigned k=0;k<c.width;++k)v.push_back(static_cast<unsigned char>(pixel(j,k)));return v;}
 std::vector<unsigned char>encoded()const{std::vector<unsigned char>v;for(unsigned j=0;j<c.height;++j){const auto e=encode(row(j));v.insert(v.end(),e.begin(),e.end());}return v;}
 void setup(b::Memory&m,unsigned char*a,b::HeapAdapter&h)const{need((root==0x28f870u||root==0x28f9a0u)&&h.addresses.empty(),"1084 selectedroot validemptyownedpool");check_literals(m);for(unsigned k=0;k<arena_size;++k)a[k]=static_cast<unsigned char>(b::mix(c.seed+131u*k));for(unsigned k=0;k<128u;++k)m.w8(0xaa5050u+k,b::mix(c.seed+43u*k));const auto data=h.allocate(c.capacity);need(data&&encoded().size()+12u<c.capacity,"1084 realfixture allocation and strictlysparecapacity");m.w32(receiver(),c.capacity);m.w32(receiver()+4u,data);m.w32(receiver()+8u,data);m.w32(surface(),0x785ef8u);m.w32(surface()+4u,256u);m.w32(surface()+8u,256u);m.w32(surface()+12u,0u);m.w32(surface()+16u,1u);m.w32(surface()+20u,pixels());m.w32(surface()+24u,65536u);m.w8(surface()+28u,0u);for(unsigned j=0;j<c.height;++j)for(unsigned k=0;k<c.width;++k)m.w8(pixels()+(y()+j)*256u+x()+k,pixel(j,k));const unsigned a0=root==0x28f870u?c.dx:x(),a1=root==0x28f870u?c.dy:y();m.w32(input_record(),a0);m.w32(input_record()+4u,a1);const unsigned rect=input_record()+(root==0x28f870u?8u:0u);m.w32(rect,x());m.w32(rect+4u,y());m.w32(rect+8u,c.width);m.w32(rect+12u,c.height);}
 b::Inputs input()const{b::Inputs i{};i.ax=b::mix(c.seed+1u);i.cx=receiver();i.dx=b::mix(c.seed+2u);for(unsigned k=0;k<16u;++k)i.arg[k]=b::mix(c.seed+73u*k+17u);i.arg[0]=surface();i.arg[1]=input_record();if(root==0x28f9a0u){i.arg[2]=c.dx;i.arg[3]=c.dy;}return i;}
 std::array<unsigned,16>caller()const{auto a=input().arg;if(root==0x28f870u)a[1]=pixel_end();else{a[2]=pixel_end();a[3]=c.height;}return a;}
 ra2::platform::x87::Image expected_fp()const{return ra2::platform::x87::Image::empty(static_cast<std::uint16_t>(c.control));}
 Proof prove(const b::HeapAdapter&h)const{const auto live=h.live();need(live.size()==1u&&h.addresses.size()==1u&&live[0].ordinal==0u&&live[0].address==h.addresses[0u]&&live[0].bytes==c.capacity,"1084 completeLIVEpoolinventory");const auto relation=h.identify(live[0].address,live[0].bytes);need(relation.ordinal==0u&&relation.offset==0u,"1084 immutable wholeLIVEordinalproof");return{live[0].address,live[0].bytes};}
 void normalize_before(std::vector<unsigned char>&a,const b::HeapAdapter&h)const{const auto p=prove(h);for(unsigned off:{4u,8u})b::word(a,receiver()-base+off,p.token(b::readword(a,receiver()-base+off)));}
 std::vector<unsigned char>block(const b::HeapAdapter&h)const{auto v=b::fresh(0u,c.capacity);auto word16=[&](unsigned p,unsigned value){v[p]=static_cast<unsigned char>(value);v[p+1u]=static_cast<unsigned char>(value>>8u);};word16(0u,c.dx);word16(2u,c.dy);word16(4u,c.width);word16(6u,c.height);b::word(v,8u,h.addresses[0u]+12u);const auto e=encoded();std::copy(e.begin(),e.end(),v.begin()+12u);return v;}
};
struct Observation{std::vector<b::Event>events;std::vector<std::vector<unsigned char>>live,prefree;std::vector<unsigned char>image,arena;unsigned scalar{},heap_bytes{},prefree_bytes{},normalizations{};};
inline Observation verify(const World&w,b::HeapAdapter&h,unsigned eax,const ra2::platform::x87::Image&fp,const std::vector<unsigned char>&bi,const std::vector<unsigned char>&ba,const unsigned char*image,const unsigned char*arena){need(h.events().size()==1u&&h.snapshots.empty()&&h.allocation_flags.size()==1u,"1084 singlefixture allocation event/no targetalloc orfree");const auto p=w.prove(h);const auto&e=h.events()[0];need(e.kind==b::Event::Kind::allocate&&e.ordinal==0u&&e.address==p.address&&e.result==p.address&&e.size==p.size&&h.allocation_flags[0u]==0u,"1084 actual allocation extent/rawresult/flags");need(eax==p.address,"1084 complete rawEAX exactinputownedpoololdcursor");Observation o;o.events=h.events();auto ei=bi,expected=ba;for(unsigned row=0;row<w.c.height;++row){const auto encoded=encode(w.row(row));std::copy(encoded.begin(),encoded.end(),ei.begin()+0x6a5050u);}const auto end=p.address+12u+unsigned(w.encoded().size());b::word(expected,w.receiver()-w.base+8u,end);need(std::equal(ei.begin(),ei.end(),image)&&std::equal(expected.begin(),expected.end(),arena),"1084 independent wholeimage/scratchlastrow/all1MiB/surface netlock0/cursor inputrecord");o.image=ei;o.arena=expected;b::word(o.arena,w.receiver()-w.base+4u,p.token(b::readword(o.arena,w.receiver()-w.base+4u)));b::word(o.arena,w.receiver()-w.base+8u,p.token(b::readword(o.arena,w.receiver()-w.base+8u),end-p.address));o.normalizations=2u;
 std::vector<unsigned char>bytes(reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address)),reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address))+p.size);need(bytes==w.block(h),"1084 independent completeencodedrecord/header/rowlengths/zeroruns/literals/roundtailbytes");b::word(bytes,8u,p.token(b::readword(bytes,8u),12u));++o.normalizations;o.live.push_back(std::move(bytes));o.heap_bytes=p.size;o.scalar=p.token(eax);++o.normalizations;need(ra2::platform::x87::same_numeric(fp,w.expected_fp()),"1084 complete unchanged numericx87");return o;}
inline void compare(const Observation&a,const Observation&d){need(a.scalar==d.scalar&&a.image==d.image&&a.arena==d.arena&&a.live==d.live&&a.events.size()==d.events.size(),"1084 paired complete encoded pool/arena/image/return");const auto&x=a.events[0],&y=d.events[0];need(x.kind==y.kind&&x.ordinal==y.ordinal&&x.size==y.size,"1084 paired realfixtureallocation");}
inline void cleanup(b::HeapAdapter&h){if(h.live().empty())return;need(h.live().size()==1u&&h.release(h.addresses[0u])!=0u,"1084 realpoolrelease strictlyafterobservations");need(h.live().empty(),"1084 no retainedownedfixtureblocks");}
